package com.crypto.laplace.execution;
import static org.mockito.Mockito.*;import com.crypto.common.enums.PositionSide;import com.crypto.laplace.config.LaplaceStrategyProperties;import com.crypto.laplace.model.*;import com.crypto.laplace.persistence.*;import com.crypto.laplace.service.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class LaplaceCooldownSignalIsolationTest {
 @Test void rawSignalRoutesOnlyToActiveTrue(){var h=new Harness(true,signal(1,.01));h.router.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);h.router.onSignal(h.raw,true);verify(h.execution).open(same(h.raw),eq(PositionSide.SHORT),isNull(),eq("FLAT"));}
 @Test void trueSymbolStopCooldownStillBlocksSameSymbol(){var h=new Harness(true,signal(1,.01));var now=Instant.parse("2026-08-15T12:00:00Z");when(h.cooldown.active("BTCUSDT")).thenReturn(Optional.of(new LaplaceTrueSymbolStopLossCooldownService.ActiveCooldown("sl",now,now,now.plusSeconds(14400))));h.router.initializeBaseline("BTCUSDT",LaplaceSignal.NONE);h.router.onSignal(h.raw,true);verify(h.execution,never()).open(any(),any(),any(),any());}
 private static LaplaceSignalResult signal(double atr,double slope){Instant now=Instant.parse("2026-08-14T00:00:00Z");return new LaplaceSignalResult("LAPLACE_KERNEL_REGRESSION_30M","1.0","BTCUSDT","30m","LAPLACE",14,"CLOSE",false,now.minusSeconds(1800),now,100,99,98,97,1,1,atr,10,slope,.1,.03,.04,2,LaplaceSignal.LONG,LaplaceSignal.NONE,StartupState.ACTIVE,1,true,List.of());}
 private static class Harness{final LaplaceSignalResult raw;final LaplacePaperExecutionService execution=mock(LaplacePaperExecutionService.class);final LaplaceTrueSymbolStopLossCooldownService cooldown=mock(LaplaceTrueSymbolStopLossCooldownService.class);final LaplaceSignalFanOut router;Harness(boolean active,LaplaceSignalResult raw){this.raw=raw;var repo=mock(LaplacePaperPositionRepository.class);when(repo.findByStrategyAndSymbolAndStatus(any(),any(),any())).thenReturn(List.of());var runtime=mock(LaplaceRuntimeService.class);when(runtime.isActive()).thenReturn(active);router=new LaplaceSignalFanOut(new LaplacePaperTradeCoordinator(new LaplaceStrategyProperties(),repo,execution,mock(LaplaceTradeJsonlWriter.class),runtime,mock(LaplaceDiagnosticLogService.class),cooldown));}}
}
